 2	    modifies nums
 3	    requires 0 <= nums.Length <= 100
 4	    requires forall i :: 0 <= i < nums.Length ==> 0 <= nums[i] <= 50
 5	    requires 0 <= val <= 100
 6	    ensures forall j :: 0 < j < i < nums.Length ==> nums[j] != val
 7	{
 8	    i := 0;
 9	    var end := nums.Length - 1;
10	
11	    while i <= end 
12	        invariant 0 <= i <= nums.Length
13	        invariant end < nums.Length
14	    {
15	        if (nums[i] == val)
16	        {
17	            if (nums[end] == val)
18	            {
19	                end := end - 1;
20	            }
21	            else {
22	                nums[i] := nums[end];
23	                i := i + 1;
24	                end := end  - 1;
25	            }
26	        }
27	        else {
28	            i := i + 1;
29	        }
30	    }
31	}
